// Bitmap font (font_pixel): 5x7 glyphs, A-Z 0-9 and punctuation.

import { makeCanvas } from './pix.js';

const G = {};
const def = (ch, ...rows) => { G[ch] = rows; };

def('A', '.###.', '#...#', '#...#', '#####', '#...#', '#...#', '#...#');
def('B', '####.', '#...#', '#...#', '####.', '#...#', '#...#', '####.');
def('C', '.####', '#....', '#....', '#....', '#....', '#....', '.####');
def('D', '####.', '#...#', '#...#', '#...#', '#...#', '#...#', '####.');
def('E', '#####', '#....', '#....', '####.', '#....', '#....', '#####');
def('F', '#####', '#....', '#....', '####.', '#....', '#....', '#....');
def('G', '.####', '#....', '#....', '#.###', '#...#', '#...#', '.####');
def('H', '#...#', '#...#', '#...#', '#####', '#...#', '#...#', '#...#');
def('I', '#####', '..#..', '..#..', '..#..', '..#..', '..#..', '#####');
def('J', '..###', '...#.', '...#.', '...#.', '...#.', '#..#.', '.##..');
def('K', '#...#', '#..#.', '#.#..', '##...', '#.#..', '#..#.', '#...#');
def('L', '#....', '#....', '#....', '#....', '#....', '#....', '#####');
def('M', '#...#', '##.##', '#.#.#', '#.#.#', '#...#', '#...#', '#...#');
def('N', '#...#', '##..#', '#.#.#', '#..##', '#...#', '#...#', '#...#');
def('O', '.###.', '#...#', '#...#', '#...#', '#...#', '#...#', '.###.');
def('P', '####.', '#...#', '#...#', '####.', '#....', '#....', '#....');
def('Q', '.###.', '#...#', '#...#', '#...#', '#.#.#', '#..#.', '.##.#');
def('R', '####.', '#...#', '#...#', '####.', '#.#..', '#..#.', '#...#');
def('S', '.####', '#....', '#....', '.###.', '....#', '....#', '####.');
def('T', '#####', '..#..', '..#..', '..#..', '..#..', '..#..', '..#..');
def('U', '#...#', '#...#', '#...#', '#...#', '#...#', '#...#', '.###.');
def('V', '#...#', '#...#', '#...#', '#...#', '#...#', '.#.#.', '..#..');
def('W', '#...#', '#...#', '#...#', '#.#.#', '#.#.#', '##.##', '#...#');
def('X', '#...#', '#...#', '.#.#.', '..#..', '.#.#.', '#...#', '#...#');
def('Y', '#...#', '#...#', '.#.#.', '..#..', '..#..', '..#..', '..#..');
def('Z', '#####', '....#', '...#.', '..#..', '.#...', '#....', '#####');
def('0', '.###.', '#...#', '#..##', '#.#.#', '##..#', '#...#', '.###.');
def('1', '..#..', '.##..', '..#..', '..#..', '..#..', '..#..', '.###.');
def('2', '.###.', '#...#', '....#', '...#.', '..#..', '.#...', '#####');
def('3', '####.', '....#', '....#', '.###.', '....#', '....#', '####.');
def('4', '...#.', '..##.', '.#.#.', '#..#.', '#####', '...#.', '...#.');
def('5', '#####', '#....', '#....', '####.', '....#', '....#', '####.');
def('6', '.###.', '#....', '#....', '####.', '#...#', '#...#', '.###.');
def('7', '#####', '....#', '...#.', '..#..', '.#...', '.#...', '.#...');
def('8', '.###.', '#...#', '#...#', '.###.', '#...#', '#...#', '.###.');
def('9', '.###.', '#...#', '#...#', '.####', '....#', '....#', '.###.');
def('.', '.....', '.....', '.....', '.....', '.....', '.##..', '.##..');
def(',', '.....', '.....', '.....', '.....', '.##..', '..#..', '.#...');
def(':', '.....', '.##..', '.##..', '.....', '.##..', '.##..', '.....');
def('!', '..#..', '..#..', '..#..', '..#..', '..#..', '.....', '..#..');
def('?', '.###.', '#...#', '....#', '...#.', '..#..', '.....', '..#..');
def('+', '.....', '..#..', '..#..', '#####', '..#..', '..#..', '.....');
def('-', '.....', '.....', '.....', '#####', '.....', '.....', '.....');
def('/', '....#', '....#', '...#.', '..#..', '.#...', '#....', '#....');
def('%', '##..#', '##..#', '...#.', '..#..', '.#...', '#..##', '#..##');
def("'", '..#..', '..#..', '.#...', '.....', '.....', '.....', '.....');
def('[', '.###.', '.#...', '.#...', '.#...', '.#...', '.#...', '.###.');
def(']', '.###.', '...#.', '...#.', '...#.', '...#.', '...#.', '.###.');
def('<', '...#.', '..#..', '.#...', '#....', '.#...', '..#..', '...#.');
def('>', '.#...', '..#..', '...#.', '....#', '...#.', '..#..', '.#...');
def('=', '.....', '.....', '#####', '.....', '#####', '.....', '.....');
def(' ', '.....', '.....', '.....', '.....', '.....', '.....', '.....');

export const GLYPHS = G;
export const GLYPH_ORDER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.,:!?+-/%'[]<>= ";
export const GLYPH_W = 5;
export const GLYPH_H = 7;

// Draw a glyph string into a Pix at (ox, oy) with the given scale and color.
export function blitText(pix, str, ox, oy, scale, color) {
  str = str.toUpperCase();
  for (let i = 0; i < str.length; i++) {
    const rows = G[str[i]];
    if (!rows) continue;
    for (let y = 0; y < GLYPH_H; y++) for (let x = 0; x < GLYPH_W; x++) {
      if (rows[y][x] !== '#') continue;
      pix.rect(ox + (i * 6 + x) * scale, oy + y * scale, scale, scale, color);
    }
  }
}

export function textWidth(str, scale) {
  return str.length ? str.length * 6 * scale - scale : 0;
}

export class Font {
  constructor(stripCanvas) {
    this.strip = stripCanvas;
    this.cache = new Map();
  }

  colored(color) {
    let c = this.cache.get(color);
    if (!c) {
      c = makeCanvas(this.strip.width, this.strip.height);
      const x = c.getContext('2d');
      x.drawImage(this.strip, 0, 0);
      x.globalCompositeOperation = 'source-in';
      x.fillStyle = color;
      x.fillRect(0, 0, c.width, c.height);
      this.cache.set(color, c);
    }
    return c;
  }

  width(str, scale) {
    return textWidth(str, scale);
  }

  // opts: { align: 'left'|'center'|'right', outline: color, shadow: color }
  draw(ctx, str, x, y, scale = 1, color = '#ffffff', opts = {}) {
    str = String(str).toUpperCase();
    const w = this.width(str, scale);
    if (opts.align === 'center') x -= Math.floor(w / 2);
    else if (opts.align === 'right') x -= w;
    x = Math.round(x);
    y = Math.round(y);
    if (opts.outline) {
      const oc = this.colored(opts.outline);
      const o = opts.outlineW || Math.min(scale, 2);
      const offs = [[-o, 0], [o, 0], [0, -o], [0, o], [-o, -o], [o, -o], [-o, o], [o, o]];
      for (const [dx, dy] of offs) this._raw(ctx, oc, str, x + dx, y + dy, scale);
    }
    if (opts.shadow) this._raw(ctx, this.colored(opts.shadow), str, x + scale, y + scale, scale);
    this._raw(ctx, this.colored(color), str, x, y, scale);
    return w;
  }

  _raw(ctx, img, str, x, y, s) {
    for (let i = 0; i < str.length; i++) {
      const ch = str[i];
      if (ch === ' ') continue;
      const gi = GLYPH_ORDER.indexOf(ch);
      if (gi < 0) continue;
      ctx.drawImage(img, gi * GLYPH_W, 0, GLYPH_W, GLYPH_H, x + i * 6 * s, y, GLYPH_W * s, GLYPH_H * s);
    }
  }
}
